// reviewsData.ts
export interface ReviewData {
    reviewer: string;
    lessons: number;
    quote: string;
  }

  const reviews: ReviewData[] = [
    {
      reviewer: "John Doe",
      lessons: 10,
      quote: "Great tutor! Highly recommended."
    },
    {
      reviewer: "Jane Smith",
      lessons: 8,
      quote: "Oliver is very knowledgeable and patient."
    },
    {
      reviewer: "Emma Brown",
      lessons: 15,
      quote: "My skills have improved tremendously thanks to Oliver's guidance."
    },
  ];

  export default reviews;
